360	  modrinth: "Modrinth",
361	  spigotmc: "SpigotMC",
362	  hangar: "Hangar",
363	  curseforge: "CurseForge",
364	  steam_workshop: "Steam Workshop",
365	  umod: "uMod",
366	  github: "GitHub",
367	  nexus: "Nexus Mods",
368	  thunderstore: "Thunderstore",
369	  codefling: "Codefling",
370	};
