import Link from "next/link";
import type { ModSummary } from "@/lib/mods-catalog";
import type { CatalogSort } from "@/lib/mods-catalog";
import { buildHref } from "@/lib/pagination";
import { ModCard } from "./ModCard";
import { QuickAddButton, type QuickAddServer } from "./QuickAddButton";
import { IconSearch, IconArrow } from "./icons";

/**
 * The interactive core of NxLabs's browse experience — search, chip
 * filtering, sort, and paging. Until 2026-09-19 all four ran client-side
 * (`useState`/`useMemo`) over the whole array the server component fetched
 * up front, which was genuinely fine at ~124 hand-seeded rows and quietly
 * broken the moment a real bulk import (scripts/import-modrinth-catalog.ts)
 * landed 32,000+ rows in one family: the server capped what it fetched at
 * 400, so there was no page 2 at all, AND the search box's own placeholder
 * ("Search mods, plugins, and more…") promises to search the catalogue, not
 * whatever 400-or-fewer rows happened to already be loaded — a client-side
 * `.filter()` over a partial array would silently under-report or entirely
 * miss real matches outside that window.
 *
 * So this is now a Server Component: `mods` is just the current page,
 * already filtered/sorted/paginated by `lib/mods-catalog.ts`'s
 * `queryCatalogMods()`, and every control here is a plain link or a native
 * GET `<form>` that re-requests the page with new searchParams — the same
 * pattern this codebase already uses for /blog's search+pager
 * (app/blog/page.tsx) and the admin tables (lib/pagination.ts). No client
 * JS is required for the store to work at all; QuickAddButton (the one
 * genuinely interactive bit — installing onto a real server) stays its own
 * small Client Component underneath.
 */
export type SortKey = CatalogSort;

const SORTS: { key: SortKey; label: string }[] = [
  { key: "featured", label: "Featured" },
  { key: "downloads", label: "Most Downloaded" },
  { key: "latest", label: "Latest" },
  { key: "rating", label: "Top Rated" },
];

export function StoreBrowser({
  mods,
  total,
  page,
  totalPages,
  chips,
  chipField,
  activeChipKey,
  basePath,
  q,
  sort,
  showGameBadge = false,
  serversByFamily,
  deployHref,
  searchPlaceholder = "Search mods, plugins, and more…",
  emptyLabel = "No mods match your filters yet.",
}: {
  /** The current page's rows only — already the real, server-side filtered/sorted/paginated set. */
  mods: ModSummary[];
  /** Real total row count for the active filters (not just this page). */
  total: number;
  page: number;
  totalPages: number;
  /**
   * Real, DB-wide counts (never derived from `mods`, which is only one
   * page). When `href` is set, the chip navigates to a different route
   * entirely (the cross-game pages point family chips at the real
   * `/games/[family]` pages instead of re-filtering in place); otherwise it
   * links to this same route with `?category=` set.
   */
  chips: { key: string; label: string; count: number; href?: string }[];
  chipField: "gameFamily" | "category";
  /** Which chip (by key) is the active filter — only meaningful when chipField is "category"; gameFamily chips always navigate away instead. */
  activeChipKey?: string;
  /** This route's own path (no query string) — every link below is built from it. `${basePath}/${mod.gameFamily}/${mod.slug}` is still the detail-page href. */
  basePath: string;
  /** Current `?q=`. */
  q?: string;
  /** Current `?sort=`. */
  sort?: SortKey;
  showGameBadge?: boolean;
  /** Portal only: this viewer's eligible servers per game family, for the QuickAddButton row. */
  serversByFamily?: Record<string, QuickAddServer[]>;
  /** Portal only: where "order one" points when there's no matching server. */
  deployHref?: string;
  searchPlaceholder?: string;
  emptyLabel?: string;
}) {
  const activeSort = sort ?? "featured";
  const query = q ?? "";

  /** Build a link on this same route, preserving q/sort/category unless overridden. Omitting `page` resets to page 1 — the right default whenever the filter itself changes. */
  const hrefFor = (next: { page?: number; sort?: SortKey; category?: string | null; q?: string }) =>
    buildHref(basePath, {
      q: next.q ?? query,
      sort: (next.sort ?? activeSort) === "featured" ? undefined : (next.sort ?? activeSort),
      category: next.category === null ? undefined : (next.category ?? activeChipKey),
      page: next.page ?? 1,
    });

  const from = total === 0 ? 0 : (page - 1) * (mods[0] ? Math.max(mods.length, 1) : 0) + 1;
  // `from`/`to` from the real page size (perPage isn't passed down — derive
  // it from page/total/mods.length, which is exact for every page except a
  // short last page, where mods.length alone already gives the right `to`).
  const perPageGuess = totalPages > 1 && page < totalPages ? mods.length : undefined;
  const rangeFrom = total === 0 ? 0 : perPageGuess ? (page - 1) * perPageGuess + 1 : (page - 1) * mods.length + 1;
  const rangeTo = total === 0 ? 0 : rangeFrom + mods.length - 1;

  return (
    <div>
      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <form method="get" action={basePath} className="relative w-full sm:max-w-xs">
          <IconSearch
            className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--fg-muted)]"
            size={16}
          />
          <input
            type="search"
            name="q"
            defaultValue={query}
            placeholder={searchPlaceholder}
            aria-label="Search mods"
            className="input w-full pl-9 text-sm"
          />
          {activeSort !== "featured" && <input type="hidden" name="sort" value={activeSort} />}
          {chipField === "category" && activeChipKey && <input type="hidden" name="category" value={activeChipKey} />}
        </form>
        <div className="flex flex-wrap gap-1 rounded-full border border-white/10 p-1">
          {SORTS.map((s) => (
            <Link
              key={s.key}
              href={hrefFor({ sort: s.key })}
              className={`rounded-full px-3 py-1.5 text-xs font-medium transition-colors ${
                activeSort === s.key ? "bg-brand-500 text-white" : "text-[var(--fg-muted)] hover:text-[var(--fg)]"
              }`}
            >
              {s.label}
            </Link>
          ))}
        </div>
      </div>

      {chips.length > 0 && (
        <div className="mb-6 flex flex-wrap gap-2">
          <Link
            href={chipField === "gameFamily" ? basePath : hrefFor({ category: null })}
            className={`rounded-full border px-4 py-1.5 text-sm ${
              !activeChipKey ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
            }`}
          >
            All
          </Link>
          {chips.map((c) => (
            <Link
              key={c.key}
              href={c.href ?? hrefFor({ category: c.key })}
              className={`rounded-full border px-4 py-1.5 text-sm ${
                activeChipKey === c.key ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
              }`}
            >
              {c.label} ({c.count})
            </Link>
          ))}
        </div>
      )}

      {mods.length === 0 ? (
        <p className="py-12 text-center text-sm text-[var(--fg-muted)]">{emptyLabel}</p>
      ) : (
        <>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
            {mods.map((mod) => {
              const matching = serversByFamily?.[mod.gameFamily] ?? [];
              return (
                <div key={mod.id} className="flex flex-col gap-2">
                  <ModCard mod={mod} href={`${basePath}/${mod.gameFamily}/${mod.slug}`} showGameBadge={showGameBadge} />
                  {serversByFamily &&
                    (matching.length > 0 ? (
                      <QuickAddButton modId={mod.id} servers={matching} />
                    ) : (
                      <p className="text-xs text-tx-mute">
                        No matching server yet —{" "}
                        <a href={deployHref ?? "/dashboard/deploy"} className="text-brand-300 underline underline-offset-2">
                          order one
                        </a>
                        .
                      </p>
                    ))}
                </div>
              );
            })}
          </div>

          <Pager page={page} totalPages={totalPages} total={total} rangeFrom={rangeFrom} rangeTo={rangeTo} hrefFor={hrefFor} />
        </>
      )}
    </div>
  );
}

/** Real Prev/Next + numbered pager, plus honest "X–Y of N mods" copy — no fake page counts. */
function Pager({
  page,
  totalPages,
  total,
  rangeFrom,
  rangeTo,
  hrefFor,
}: {
  page: number;
  totalPages: number;
  total: number;
  rangeFrom: number;
  rangeTo: number;
  hrefFor: (next: { page: number }) => string;
}) {
  const linkCls =
    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.03] px-3 text-sm font-medium text-[var(--fg-muted)] transition-colors hover:border-brand-400/50 hover:text-[var(--fg)]";
  const disabledCls =
    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-transparent px-3 text-sm font-medium text-[var(--fg-muted)]/40 cursor-not-allowed";

  const windowStart = Math.max(1, page - 2);
  const windowEnd = Math.min(totalPages, page + 2);
  const pages: number[] = [];
  for (let i = windowStart; i <= windowEnd; i++) pages.push(i);

  return (
    <div className="mt-8 flex flex-col items-center gap-3">
      <p className="text-xs text-[var(--fg-muted)]">
        {total === 0 ? "0 mods" : `${rangeFrom.toLocaleString()}–${rangeTo.toLocaleString()} of ${total.toLocaleString()} mods`}
      </p>
      {totalPages > 1 && (
        <nav className="flex flex-wrap items-center justify-center gap-2" aria-label="Mods pagination">
          {page > 1 ? (
            <Link href={hrefFor({ page: page - 1 })} rel="prev" className={linkCls} aria-label="Previous page">
              <IconArrow size={13} className="rotate-180" /> Prev
            </Link>
          ) : (
            <span className={disabledCls} aria-hidden>
              <IconArrow size={13} className="rotate-180" /> Prev
            </span>
          )}

          {windowStart > 1 && (
            <>
              <Link href={hrefFor({ page: 1 })} className={linkCls}>
                1
              </Link>
              {windowStart > 2 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
            </>
          )}

          {pages.map((n) =>
            n === page ? (
              <span
                key={n}
                aria-current="page"
                className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-300"
              >
                {n}
              </span>
            ) : (
              <Link key={n} href={hrefFor({ page: n })} className={linkCls}>
                {n}
              </Link>
            )
          )}

          {windowEnd < totalPages && (
            <>
              {windowEnd < totalPages - 1 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
              <Link href={hrefFor({ page: totalPages })} className={linkCls}>
                {totalPages}
              </Link>
            </>
          )}

          {page < totalPages ? (
            <Link href={hrefFor({ page: page + 1 })} rel="next" className={linkCls} aria-label="Next page">
              Next <IconArrow size={13} />
            </Link>
          ) : (
            <span className={disabledCls} aria-hidden>
              Next <IconArrow size={13} />
            </span>
          )}
        </nav>
      )}
    </div>
  );
}

