import { notFound } from "next/navigation";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { familyFor } from "@/lib/game-config";
import { PageShell } from "@/components/nx/PageShell";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import type { QuickAddServer } from "@/components/mods/QuickAddButton";
import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { listCatalogFamilies, listCategoryCounts, queryCatalogMods, totalDownloadsFor, formatDownloads } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

type Search = { q?: string; sort?: string; category?: string; page?: string };

/** Portal's own per-game NxLabs page — same data as the marketing one, own chrome/route (item 7). */
export default async function PortalGameModsPage({
  params,
  searchParams,
}: {
  params: Promise<{ family: string }>;
  searchParams: Promise<Search>;
}) {
  const { family } = await params;
  const user = await requireUser();

  const families = await listCatalogFamilies();
  const entry = families.find((f) => f.family === family);
  if (!entry) notFound();

  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const category = sp.category?.trim() || undefined;
  const page = Number(sp.page) || 1;

  const [categoryCounts, result, totalDownloads, myServers] = await Promise.all([
    listCategoryCounts(family),
    queryCatalogMods({ family, category, q, sort, page }),
    totalDownloadsFor(family),
    db.server.findMany({ where: { userId: user.id, status: { notIn: ["DELETING"] } }, include: { osTemplate: true, gamePlan: true } }),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;

  const myMatchingServers: QuickAddServer[] = myServers
    .filter((s) => familyFor(s) === family)
    .map((s) => ({ id: s.id, hostname: s.hostname, label: s.label }));

  const label = GAME_DISPLAY[family as GameFamily]?.name ?? entry.label;
  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;

  const chips = categoryCounts.map((c) => ({ key: c.category, label: c.category, count: c.count }));

  return (
    <PageShell
      eyebrow="NxLabs"
      title={`${label} mods & plugins`}
      sub={`${entry.count} verified add-ons for ${label}${totalDownloads > 0 ? ` — ${formatDownloads(totalDownloads)} total downloads` : ""}.`}
      tagline={["VERIFIED SOURCES.", "ONE-CLICK INSTALL."]}
      heroImage={heroSlug ? `/games/art/${heroSlug}_hero.jpg` : undefined}
    >
      <StoreBrowser
        mods={mods}
        total={total}
        page={resolvedPage}
        totalPages={totalPages}
        perPage={perPage}
        chips={chips}
        chipField="category"
        activeChipKey={category}
        basePath="/dashboard/nxlabs"
        browsePath={`/dashboard/nxlabs/games/${family}`}
        q={q}
        sort={sort}
        searchPlaceholder={`Search ${label} mods…`}
        serversByFamily={{ [family]: myMatchingServers }}
        deployHref="/dashboard/deploy"
      />
    </PageShell>
  );
}

